// Modo: Run Once for All Items.
// Avanza el offset, deja constancia del latido y saca UN item, siempre, haya
// mensajes o no: de ese item cuelga la rellamada que mantiene viva la cadena.

const estado = $getWorkflowStaticData('global');
const respuesta = $input.first().json;

const updates = (respuesta.ok && Array.isArray(respuesta.result)) ? respuesta.result : [];

let offset = $('Leer offset').first().json.offset;
if (updates.length > 0) {
  offset = Math.max(...updates.map(u => u.update_id)) + 1;
}

estado.telegramOffset = offset;
estado.ultimoLatido = Date.now();

return [{ json: { offset, updates, hay: updates.length } }];

// Modo: Run Once for All Items.
// El eslabon anterior de la cadena nos pasa el offset ya avanzado en su propia
// salida. No podemos leerlo de staticData: n8n solo lo guarda al TERMINAR la
// ejecucion, y para entonces este poll ya habria salido con el valor viejo y
// reprocesaria los mismos mensajes.
// Por la rama de rescate no viene nada y ahi si tiramos de staticData.

const estado = $getWorkflowStaticData('global');
const entrada = $input.first()?.json ?? {};

const offset = Number.isFinite(entrada.offset)
  ? entrada.offset
  : (estado.telegramOffset ?? 0);

return [{ json: { offset } }];

// Modo: Run Once for All Items.
// Puerta de entrada y normalizacion. Un item por cosa que haya que atender.

const PERMITIDO = Number($env.TELEGRAM_ALLOWED_USER_ID);

if (!Number.isFinite(PERMITIDO) || PERMITIDO === 0) {
  throw new Error('TELEGRAM_ALLOWED_USER_ID no esta definido en el contenedor de n8n');
}

const updates = $input.first().json.updates ?? [];
const salida = [];

for (const u of updates) {
  // Boton de confirmacion pulsado.
  if (u.callback_query) {
    const cq = u.callback_query;
    if (cq.from?.id !== PERMITIDO) continue;
    salida.push({
      json: {
        update_id: u.update_id,
        clase: 'callback',
        callback_id: cq.id,
        chat_id: cq.message?.chat?.id ?? null,
        message_id: cq.message?.message_id ?? null,
        datos: cq.data ?? '',
      },
    });
    continue;
  }

  const msg = u.message;
  if (!msg) continue;
  if (msg.from?.id !== PERMITIDO) continue;

  salida.push({
    json: {
      update_id: u.update_id,
      clase: 'mensaje',
      chat_id: msg.chat.id,
      message_id: msg.message_id,
      fecha: new Date(msg.date * 1000).toISOString(),
      tipo: msg.voice ? 'voz' : (msg.text ? 'texto' : 'otro'),
      texto: msg.text ?? null,
      voice_file_id: msg.voice?.file_id ?? null,
      voice_duracion: msg.voice?.duration ?? null,
    },
  });
}

return salida;

// Modo: Run Once for All Items.
// Solo corre por la rama del Schedule de rescate. Si la cadena sigue viva no
// arrancamos otra: dos getUpdates a la vez sobre el mismo bot son un 409.

const MAX_SILENCIO_MS = 120 * 1000;

const estado = $getWorkflowStaticData('global');
const ultimo = estado.ultimoLatido ?? 0;

if (Date.now() - ultimo < MAX_SILENCIO_MS) {
  return [];   // hay latido reciente, no tocamos nada
}

return [{ json: { rescate: true } }];
